mapper.update:
UPDATE chat_message
SET is_deleted = TRUE
WHERE message_id = #{messageId}

mapper.select:
SELECT message_id, chat_id, sender_id, message_type, content, is_deleted, created_at FROM ( SELECT message_id, chat_id, sender_id, message_type, content, is_deleted, created_at FROM chat_message WHERE chat_id = #{chatId} AND is_deleted = FALSE
AND message_id < #{beforeMessageId}
ORDER BY created_at DESC LIMIT 30 ) recent_messages ORDER BY created_at ASC

SELECT COUNT(*)
FROM chat_message
WHERE chat_id = #{chatId}
  AND is_deleted = FALSE
  AND sender_id != #{userId}
  AND message_id > COALESCE(#{lastReadMessageId}, 0)

SELECT COUNT(*)
FROM chat_participant
WHERE chat_id = #{chatId}
  AND user_id != #{senderId}
  AND left_at IS NULL
  AND COALESCE(last_read_message_id, 0) < #{messageId}
